from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}
    anonymous = []

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' not in event:
            anonymous.append((position, event))
            continue

        event_id = event['id']
        revision = event.get('revision', 0)
        previous = winners.get(event_id)
        if previous is None or revision >= previous[0]:
            winners[event_id] = (revision, position, event)

    selected = anonymous + [
        (position, event)
        for _, position, event in winners.values()
    ]
    selected.sort(key=lambda item: item[0])

    balances = dict(data.get('opening', {}))
    for _, event in selected:
        if event.get('void', False):
            continue
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}

def _round_ratio(numerator, mode):
    if mode == 'floor':
        return numerator // 10000
    if mode == 'half_up':
        return (numerator + 5000) // 10000
    raise ValueError(f'unsupported rounding mode: {mode}')


def amount(event, mode):
    gross = event['price'] * event.get('quantity', 1)
    discount_bp = max(0, min(10000, event.get('discount_bp', 0)))
    net = _round_ratio(gross * (10000 - discount_bp), mode)
    tax = _round_ratio(net * event.get('tax_bp', 0), mode)
    total = net + tax
    return -total if event.get('kind') == 'refund' else total
